#### 2) Example Node.js script (export refunds to CSV)
```js
// pull_refunds_last_month.js
// NOTE: This template uses placeholders. Adjust endpoint/fields to your processor.

const fetch = require("node-fetch");
const fs = require("fs");

function getLastMonthRange(now = new Date()) {
  const firstThisMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const firstLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  return { start: firstLastMonth.toISOString(), end: firstThisMonth.toISOString() };
}

const API_KEY = process.env.PAYMENT_PROCESSOR_API_KEY;
const BASE_URL = process.env.PAYMENT_PROCESSOR_BASE_URL || "https://api.processor.example/v1";

if (!API_KEY) {
  throw new Error("Missing PAYMENT_PROCESSOR_API_KEY in environment variables.");
}

const { start, end } = getLastMonthRange();
const outFile = "refunds_last_month.csv";

async function fetchAllRefunds() {
  // Many processors require pagination. This is a generic pattern.
  let all = [];
  let cursor = null;

  while (true) {
    const url = new URL(`${BASE_URL}/refunds`);
    url.searchParams.set("created_after", start);
    url.searchParams.set("created_before", end);
    url.searchParams.set("limit", "100");
    if (cursor) url.searchParams.set("starting_after", cursor);

    const res = await fetch(url.toString(), {
      method: "GET",
      headers: {
        "Authorization": `Bearer ${API_KEY}`,
        "Content-Type": "application/json",
      },
    });

    if (!res.ok) {
      const text = await res.text();
      throw new Error(`Refunds API error: ${res.status} ${res.statusText}\n${text}`);
    }

    const data = await res.json();

    // Adapt field names based on your processor response.
    const refunds = data.refunds || data.data || [];
    all.push(...refunds);

    // Pagination adaptation: cursor can be in data.next_cursor, data.has_more, etc.
    if (data.has_more) {
      cursor = data.next_cursor || refunds[refunds.length - 1].id;
    } else {
      break;
    }
  }

  return all;
}

function toCsv(rows) {
  // Columns you want in the spreadsheet.
  const columns = [
    "refund_id",
    "payment_id",
    "customer_ref",
    "card_last4",
    "amount",
    "currency",
    "created_at",
    "status",
  ];

  const escape = (val) => {
    if (val === null || val === undefined) return "";
    const s = String(val);
    // Basic CSV escaping
    if (/[",\n]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
    return s;
  };

  const header = columns.join(",");
  const lines = rows.map((r) =>
    columns.map((c) => {
      // Adapt mapping based on processor response structure.
      switch (c) {
        case "refund_id":
          return r.id;
        case "payment_id":
          return r.payment_id || r.original_payment_id;
        case "customer_ref":
          return r.customer_id || r.customer_ref;
        case "card_last4":
          return r.payment_method_details?.card_last4 || r.card_last4;
        case "amount":
          return r.amount;
        case "currency":
          return r.currency;
        case "created_at":
          return r.created_at || r.created;
        case "status":
          return r.status;
        default:
          return "";
      }
    }).join(",")
  );

  return [header, ...lines].join("\n");
}

async function main() {
  const refunds = await fetchAllRefunds();
  const csv = toCsv(refunds);
  fs.writeFileSync(outFile, csv, "utf8");
  console.log(`Exported ${refunds.length} refunds to ${outFile}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
```

#### 3) Run it
